internal val COUNTRY_NAMES_SHN: String =
    "root\u001F01ဢႅၼ်ႇတူဝ်ႇရႃႇ\u001Eမိူင်းႁူမ်ႈတုမ် ၸဝ်ႈၾႃႉ ဢႃႇရၢပ်ႈ\u001Eဢႃႇၾၵၢၼ်ႇၼီႇသတၢၼ်ႇ\u001Eဢႅၼ်ႇထီႇၵႂႃႇ လႄႈ ပႃႇပူးတႃႇ\u001Eဢႅၼ်ႇၵုၺ်ႇလႃႇ\u001Eဢႃႇပႃးၼီးယႃး\u001Eဢႃႇမေးၼီးယႃး\u001Eဢႅၼ်ႇၵူဝ်ႇလႃႇ\u001Eဢႅၼ်ႇတၢၵ်ႈတီးၵႃႈ\u001Eဢႃႇၵျႅၼ်ႇတီးၼႃး\u001Eသႃႇမူဝ်းဝႃႇ ၶွ​င် ဢမႄႇရိၵၢၼ်ႇ\u001Eဢေႃးသထရီးယႃး\u001Eဢေႃႉသထရေးလီးယႃး\u001Eဢႃႇရူးပႃး\u001Eမူႇၵုၼ် ဢေႃးလႅၼ်ႇ\u001Eဢႃႇၸႃႇပၢႆႇၸၼ်ႇ\u001Eပေႃးသၼီးယႃး လႄႈ ႁႃႇၸီႇၵူဝ်းဝီးၼႃး\u001Eပႃးပေႇတူတ်ႈ\u001Eပင်းၵလႃးတဵတ်ႈ\u001Eပႄႇၵျီႇယမ်ႇ\u001Eပူႇၵီႇၼႃးၾႃးသူဝ်ႇ\u001Eပူႇၵႃႇရီႇယႃႇ\u001Eပႃႇရဵၼ်း\u001Eပူႇရုၼ်းတီႇ\u001Eပႄႇၼိၼ်း\u001Eသဵင်ႉပႃႇထႄးလႄႇမီႇ\u001Eပႃႇမိဝ်းတႃး\u001Eပရူႇၼၢႆး\u001Eပူဝ်ႇလီးပီးယႃး\u001Eၼႄႇတႃႇလႅၼ်ႇ တီႈ ၶႃႇရိပ်ႈပီႇယၼ်ႇ\u001Eပရႃႇၸီး\u001Eပႃႇႁႃးမႃး\u001Eၽူႇတၢၼ်ႇ\u001Eမူႇၵုၼ် ပူးဝႅတ်ႉ\u001Eပွတ်ႉသဝႃႇၼႃႇ\u001Eပႄႇလႃႇရုတ်ႈ\u001Eပႄႇလိတ်ႈ\u001Eၶႅၼ်ႇၼေႇတႃႇ\u001Eမူႇၵုၼ် ၶူဝ်းၵတ်ႉ (ၶီးလိင်း)\u001Eၶွင်ႇၵူဝ်ႇ - ၶိၼ်သျႃးသႃႇ\u001Eမိူင်းႁူမ်ႈပွင်လူၺ်ႈၵူၼ်းလၢႆ ဢႃႇၾရိၵ ပွတ်းၵၢင်\u001Eၶွင်ႇၵူဝ်ႇ - ပရႃၸဝီးလ်\u001Eသဝိတ်ႈၸႃႇလႅၼ်ႇ\u001Eဢၢႆႇဝူဝ်ႇရီႇၶူတ်ႈ\u001Eမူႇၵုၼ် ၶုၵ်ႈ\u001Eၶျီႇလီႇ\u001Eၶႅမ်းမႃးရုၼ်း\u001Eၶႄႇ\u001Eၵူဝ်ႇလမ်ႇပီႇယႃႇ\u001Eၵေႃးသတႃႇရိၵႃႇ\u001Eၵူးပႃး\u001Eၶဵပ်ႉဝႄႇတီႇ\u001Eၵူးရႃႇသၢဝ်ႇ\u001Eၵုၼ်ၶရိတ်ႉသမၢတ်ႉ\u001Eသၢႆႉပရႅတ်ႈ\u001Eၶျႅၵ်ႈ\u001Eၵျႃႇမၼီႇ\u001Eၵျီႇပူးတီႇ\u001Eတႅၼ်းမၢၵ်ႈ\u001Eတူဝ်ႇမီႇၼိၵ\u001Eတူဝ်ႇမီႇၼီႇၵၼ်ႇ\u001Eဢႄးၵျီးရီးယႃး\u001Eဢေႇၵႂႃႇတေႃႇ\u001Eဢႄႇသတူဝ်းၼီးယႃး\u001Eဢီးၵျိပ်ႈ\u001Eသႃႇႁႃႇရႃႇ ပွတ်းတူၵ်း\u001Eဢႄႇရီႇထရီးယႃး\u001Eသပဵၼ်ႇ\u001Eဢီႇတီႇယူဝ်းပီးယႃး\u001Eၾိၼ်ႇလႅၼ်ႇ\u001Eၾီႇၵျီႇ\u001Eမူႇၵုၼ် ၾွၵ်ႉလႅၼ်ႇ\u001Eၼႃႈလိၼ် မၢႆႇၶရူဝ်ႇၼေးသျၼ်း\u001Eမူႇၵုၼ် ၾႄးရူဝ်း\u001Eၾရၢင်ႇသဵတ်ႈ\u001Eၵႄးပုၼ်ႇ\u001Eမိူင်းႁူမ်ႈတုမ်ႁေႃၶမ်း ပရိတ်ႈတဵၼ်ႇ\u001Eၵရႄႇၼႃႇတႃႇ\u001Eၵျေႃႇၵျႃႇ\u001Eၵုၺ်ႇယႃႇၼႃႇ ၶွင် ၾရၢင်ႇသဵတ်ႈ\u001Eၵႂၢၼ်းသီ\u001Eၵႃႇၼႃႇ\u001Eၵျီႇပရေႃးတႃး\u001Eၵရိၼ်းလႅၼ်း\u001Eၵမ်ႇပီးယႃး\u001Eၵီးၼီး\u001Eၵႂႃးတီႇလုပ်ႈ\u001Eဢီႇၵူၺ်ႇတေႃႇရီႇယႃႇ ၵီးၼီး\u001Eၵရိတ်ႈ\u001Eၵျေႃႇၵျႃႇ ပွတ်းၸၢၼ်း လႄႈ မူႇၵုၼ် သၢၼ်းဝိတ်ႉ ပွတ်းၸၢတ်း\u001Eၵႂႃႇတမႃႇလႃႇ\u001Eၵႂၢမ်ႇ\u001Eၵီးၼီး-ပိတ်ႈသၢဝ်ႇ\u001Eၵၢႆႇယႃးၼႃႇ\u001Eႁွင်းၵွင်း ၼႃႈလိၵ်ႈဢုပ်ႉပိူင်ႇၶိုၵ်ႉတွၼ်း ၶႄႇ\u001Eမူႇၵုၼ် ႁိူတ်ႉ လႄႈ မူႇၵုၼ် မႅၵ်ႇတေႃႇၼႄႇ\u001Eႁွၼ်ႇတူးရႅတ်ႈ\u001Eၶရူဝ်ႇဢေးသျႃး\u001Eႁေးတီႇ\u001Eႁၢင်ႇၵေႇရီႇ\u001Eဢိၼ်ႇတူဝ်ႇၼီးသျႃး\u001Eဢၢႆႇယႃႇလႅၼ်ႇ\u001Eဢိတ်ႇသရေး\u001Eၵုၼ်မႅၼ်း\u001Eဢိၼ်းတီးယႃး\u001Eၼႃႈလိၼ် သမုၵ်ႉတရႃႇဢိၼ်းတီးယႃး ၶွင် ဢိင်းၵလဵတ်ႈ\u001Eဢီႇရၢၵ်ႈ\u001Eဢီႇရၢၼ်း\u001Eဢၢႆးသလႅၼ်ႇ\u001Eဢီႇတႃႇလီႇ\u001Eၵျႃႇသီႇ\u001Eၵျႃႇမေႇၵႃႇ\u001Eၵျေႃႇတၼ်ႇ\u001Eၵျႃႇပၢၼ်ႇ\u001Eၶႅၼ်ႇၺႃႇ\u001Eၵႃႇၵိတ်ႈသတၼ်ႇ\u001Eၵမ်ႇပေႃးတီးယႃး\u001Eၵိရိပတီႇ\u001Eၶူဝ်ႇမူဝ်ႇရူတ်ႈ\u001Eသဵင်ႉၶိတ်ႈ လႄႈ ၼႄးဝိတ်ႈ\u001Eၵၢဝ်းလီႁွင်ႇ\u001Eၵၢဝ်းလီၸၢၼ်း\u001Eၶူႇဝဵတ်ႈ\u001Eမူႇၵုၼ် ၶေးမႅၼ်း\u001Eၵႃႇၸၢၵ်ႈသတၼ်ႇ\u001Eလၢဝ်း\u001Eလႄႇပႃႇၼွၼ်ႇ\u001Eသဵင်ႉလူႉသျႃႇ\u001Eလိၵ်ႈတိၼ်ႇသတၢႆႇ\u001Eသီႇရိလင်းၵႃ\u001Eလၢႆႇပေးရီးယႃး\u001Eလႄႇသူဝ်းတူဝ်ႇ\u001Eလီႉတူႇဝေးၼီးယႃး\u001Eလၢၵ်ႈၸိမ်ႇပၢၵ်ႈ\u001Eလၢတ်ႈဝီႇယႃႇ\u001Eလိပ်ႉပျႃး\u001Eမေႃႇရူဝ်ႇၵူဝ်ႇ\u001Eမူဝ်ႇၼႃႉၶူဝ်ႇ\u001Eမေႃႇတူဝ်းဝႃး\u001Eမွၼ်ႇတေႇၼေးၵရူဝ်ႇ\u001Eသဵင်ႉမႃႇတိၼ်\u001Eမၢတ်ႈတႃႇၵၢတ်ႈသၵႃႇ\u001Eမူႇၵုၼ် မႃးသျႄႇ\u001Eမႄႇၶေႇတူဝ်းၼီးယႃးႁွင်ႇ\u001Eမႃႇလီႇ\u001Eမျၢၼ်ႇမႃႇ (မိူင်းမၢၼ်ႈ)\u001Eမူင်ႇၵူဝ်းလီးယႃး\u001Eမႃႇၵၢဝ်ႈ ၼႃႈလိၼ်ဢုပ်ႉပိူင်ႇၶိုၵ်ႉတွၼ်း ၶႄႇ\u001Eမူႇၵုၼ် မေႇရီႇယႃႇၼႃႇ ပွတ်းႁွင်ႇ\u001Eမႃးတိၼ်ႇၼိၵ်ႈ\u001Eမေႃႇရီႇတေးၼီးယႃး\u001Eမွၼ်းသိူဝ်းရၢတ်ႈ\u001Eမေႃးတႃႇ\u001Eမေႃးရီႇသႃႇ\u001Eမေႃႇတိပ်ႈ\u001Eမႃႇလႃႇဝီႇ\u001Eမႅၵ်ႇသီႇၵူဝ်ႇ\u001Eမလေးသျႃး\u001Eမူဝ်ႇၸမ်းပိၵ်ႈ\u001Eၼႃႇမီးပီးယႃး\u001Eၼိဝ်းၶႄႇလီႇတူဝ်းၼီးယႃး\u001Eၼၢႆးၵျႃး\u001Eၵုၼ်ၼေႃႇၾုၵ်ႉ\u001Eၼၢႆႇၵျီးရီးယႃး\u001Eၼီႇၵႃႇရႃႇၵႂႃႇ\u001Eၼႄႇတႃႇလႅၼ်ႇ\u001Eၼေႃႇဝူၺ်း\u001Eၼေႇပေႃး\u001Eၼၢဝ်ရူး\u001Eၼီးဝႄႇ\u001Eၼိဝ်းၸီႇလႅၼ်ႇ\u001Eဢူဝ်ႇမၢၼ်ႇ\u001Eပႃႈၼႃးမႃး\u001Eပေႇရူႉ\u001Eပေႃႇလီႇၼေးသျႃး ၶွင် ၾရၢင်ႇသဵတ်ႈ\u001Eပႃးပႂႃႇၼိဝ်းၵီးၼီး\u001Eၾီလိပ်ႈပိၼ်း\u001Eပႃႇၵိတ်ႈသတၼ်ႇ\u001Eပူဝ်ႇလႅၼ်ႇ\u001Eသဵင်ႉပီးယႃး လႄႈ မိၵ်ႈၵွႆႇလွၼ်ႇ\u001Eမူႇၵုၼ် ၽိတ်ႉၶႅၼ်ႇ\u001Eပေႃႇတူဝ်ႇရီးၵူဝ်း\u001Eၼႃႈလိၼ် ပႃႇလႅတ်ႇသတိၼ်းၼီးယႅၼ်း\u001Eပေႃးတူႉၵၢဝ်ႇ\u001Eပႃႇလၢဝ်း\u001Eပႃႇရႃႇၵူၺ်း\u001Eၶႃႇတႃႇ\u001Eရေႇၼီႇယၼ်ႇ\u001Eရူဝ်ႇမေးၼီးယႃး\u001Eသႃးပီးယႃး\u001Eရတ်ႈသျႃး\u001Eရဝၢၼ်းတႃႇ\u001Eသေႃႇတီႇဢႃႇရေးပီးယႃး\u001Eမူႇၵုၼ် သေႃႇလေႃႇမၼ်ႇ\u001Eသေးသျႄႇ\u001Eသူႇတၼ်ႇ\u001Eသုၺ်ႇတိၼ်ႇ\u001Eသိင်ႇၵႃႇပူဝ်ႇ\u001Eသဵင်ႉႁႄးလႄးၼႃႇ\u001Eသလူဝ်ႇဝေးၼီးယႃး\u001Eသဝႃးလ်ပၢတ်ႇ လႄႈ ၸၼ်မၢႆးယႅၼ်ႇ\u001Eသလူဝ်ႇဝႃးၵီးယႃး\u001Eသီႇဢႄႇရႃႇလီႇယူၼ်ႇ\u001Eသၼ်းမႃႇရီႇၼေႃႇ\u001Eသီႇၼီႇၵႃႇ\u001Eသူဝ်ႇမႃႇလီႇယႃး\u001Eသျူးရီးၼႃႇမႄႇ\u001Eသူႇတၼ်ႇၸၢၼ်း\u001Eသူၼ်ႇတူဝ်ႇမေး လႄႈ ပရိၼ်ႇသီႇပေႇ\u001Eဢႄႇသႃႇဝႃႇတေႃႇ\u001Eသိၼ်ႉမႃႇတိၼ်ႇ\u001Eသီးရီးယႃး\u001Eဢႅတ်ႇသ်ဝႃႇတီးၼီႇ\u001Eမူႇၵုၼ် ထၢၵ်ႈ လႄႈ ၶေးၶတ်ႉ\u001Eၶျၢတ်ႈ\u001Eၼႃႈလိၼ် ၾရၢင်ႇသဵတ်ႈ ပွတ်းၸၢၼ်း\u001Eထူဝ်းၵူဝ်ႇ\u001Eမိူင်းထႆး\u001Eတႃႇၵျီႇၵီႇသတၼ်ႇ\u001Eထူဝ်းၵေႇလၢဝ်ႇ\u001Eတီႇမေႃး-လႅတ်ႉသ်တႄး\u001Eတၢၵ်ႈမႅၼ်ႇၼီႇသတၼ်ႇ\u001Eတူႇၼီးသျႃး\u001Eထွင်းၵႃႇ\u001Eတိူဝ်ႇၵီႇ\u001Eထရီႇၼီႇတၢတ်ႈ လႄႈ ထူဝ်ႇပေးၵူဝ်ႇ\u001Eထူးဝႃႇလူႇ\u001Eထၢႆႇဝၢၼ်း\u001Eထၼ်ႇၸၼ်းၼီးယႃး\u001Eယူႇၶရဵၼ်း\u001Eယူႇၵၼ်ႇတႃႇ\u001Eမူႇၵုၼ်ဢွၼ်ႇ ဢၼ်မီးၽၢႆႇၼွၵ်ႈ ယူႇဢႅတ်ႉသ်\u001Eမိူင်းႁူမ်ႈတုမ် ဢမႄႇရိၵ\u001Eဢုရုၵူၺ်း\u001Eဢူႇၸပႄႉၵိတ်ႇသတၼ်ႇ\u001Eဝႃႇတီႇၵၼ်ႇသီးတီး\u001Eသဵင်ႉဝိၼ်းသႅၼ်ႉ လႄႈ ၵရႄးၼႃးတိၼ်း\u001Eဝႄႇၼေႇၸွႆးလႃး\u001Eမူႇၵုၼ် ဝႃႇၵျိၼ်ႇ ၶွင် ဢိင်းၵလဵတ်ႈ\u001Eမူႇၵုၼ် ဝႃႇၵျိၼ်ႇ ၶွင် ယူႇဢႅတ်ႉသ်\u001Eဝႅတ်ႉၼမ်း\u001Eဝႅၼ်ႇၼူးဝႃႇထူႇ\u001Eဝႃးလိတ်ႈ လႄႈ ၾူႇတူးၼႃး\u001Eသႃႇမူဝ်းဝႃႇ\u001Eယႄႇမႅၼ်ႇ\u001Eမႃႇယူတ်ႈ\u001Eဢႃႇၾရိၵၸၢၼ်း\u001Eၸမ်းပီးယႃး\u001Eၸိမ်ႇပႃႇပူၺ်ႇ"

internal val COUNTRY_NAMES_SHN_MM: String =
